#include <bits/stdc++.h>
using namespace std;
const int SZ=10;
int light[SZ][SZ];

int solveMask(int mask){
    int press[SZ][SZ]={{0}};
    int cur[SZ][SZ];
    for(int r=0;r<SZ;r++) for(int c=0;c<SZ;c++) cur[r][c]=light[r][c];
    auto applyPress=[&](int r,int c){
        if(r<0||r>=SZ||c<0||c>=SZ) return;
        cur[r][c]^=1;
    };
    for(int c=0;c<SZ;c++) press[0][c]=(mask>>c)&1;
    for(int c=0;c<SZ;c++) if(press[0][c]){
        applyPress(0,c); applyPress(1,c); applyPress(0,c-1); applyPress(0,c+1);
    }
    for(int r=1;r<SZ;r++){
        for(int c=0;c<SZ;c++){
            if(cur[r-1][c]==1){
                press[r][c]=1;
                applyPress(r,c); applyPress(r-1,c); applyPress(r+1,c); applyPress(r,c-1); applyPress(r,c+1);
            }
        }
    }
    int cnt=0;
    for(int r=0;r<SZ;r++) for(int c=0;c<SZ;c++) cnt+=press[r][c];
    return cnt;
}

int main(){
    string name;
    while(cin>>name && name!="end"){
        for(int r=0;r<SZ;r++){
            string row; cin>>row;
            for(int c=0;c<SZ;c++) light[r][c] = row[c]=='O'?1:0;
        }
        // BUG: never checks that the last row actually ends up all-off -- just reports mask=0's
        // press count (or the smallest count seen) without verifying solvability, so it always
        // claims a numeric answer, never -1.
        cout << name << " " << solveMask(0) << "\n";
    }
}
